// Synthetic credentials of the throwaway server. They protect nothing: the
// server listens on loopback, its data directory is a temp dir, and all data
// in it is generated by this tool.
const (
	masterPW   = "sdkdiff-synthetic-master-password"            // #nosec G101 -- synthetic credential of a throwaway loopback server, protects nothing
	bootToken  = "sdkdiff-synthetic-bootstrap-token-0123456789" // #nosec G101 -- synthetic credential of a throwaway loopback server, protects nothing
	adminUser  = "sdkdiffadmin"
	adminEmail = "sdkdiffadmin@example.invalid"
	adminPW    = "Quartz-Falcon-77-Ridge!"
)

// portLineRe matches server.http.port (same anchoring idea as
// scripts/e2e/harness: the first port key under the http: block).
var portLineRe = regexp.MustCompile(`(?ms)(^server:[^\n]*\n(?:[^\n]*\n)*?  http:[^\n]*\n(?:(?:    |\s*#|\s*\n)[^\n]*\n)*?    port: )"\d+"`)

func baseEnv(dir string) []string {
	env := []string{"HOME=" + dir, "PATH=" + os.Getenv("PATH"), "KEYORIX_MASTER_PASSWORD=" + masterPW}
	if t := os.Getenv("TMPDIR"); t != "" {
		env = append(env, "TMPDIR="+t)
	}
	return env
}

func freePort() (string, error) {
	l, err := net.Listen("tcp4", "127.0.0.1:0")
	if err != nil {
		return "", err
	}
	defer l.Close() //nolint:errcheck
	return strconv.Itoa(l.Addr().(*net.TCPAddr).Port), nil
}

func setPort(dir, port string) error {
	p := filepath.Join(dir, "keyorix.yaml")
	raw, err := os.ReadFile(p) // #nosec G304 -- tool-owned temp dir
	if err != nil {
		return err
	}
	if !portLineRe.Match(raw) {
		return fmt.Errorf("server.http.port not found in generated config")
	}
	out := portLineRe.ReplaceAll(raw, []byte(fmt.Sprintf(`${1}"%s"`, port)))
	return os.WriteFile(p, out, 0o600) // #nosec G306,G703 -- tool-owned temp dir
}

// Instance is one running throwaway server.
type Instance struct {
	Dir     string
	BaseURL string
	Token   string
	cmd     *exec.Cmd
	done    chan struct{}
}

func startServer(binary, dir string, withBootstrap bool) (*Instance, error) {
	port, err := freePort()
	if err != nil {
		return nil, err
	}
	if err := setPort(dir, port); err != nil {
		return nil, err
	}
	env := append(baseEnv(dir), "KEYORIX_CONFIG_PATH=./keyorix.yaml")
	if withBootstrap {
		env = append(env, "KEYORIX_BOOTSTRAP_TOKEN="+bootToken)
	}
	logf, err := os.Create(filepath.Join(dir, "server.log")) // #nosec G304 -- tool-owned temp dir
	if err != nil {
		return nil, err
	}
	cmd := exec.Command(binary) // #nosec G204 -- operator-supplied server binary
	cmd.Dir, cmd.Env, cmd.Stdout, cmd.Stderr = dir, env, logf, logf
	if err := cmd.Start(); err != nil {
		return nil, err
	}
	in := &Instance{Dir: dir, BaseURL: "http://127.0.0.1:" + port, cmd: cmd, done: make(chan struct{})}
	go func() { _ = cmd.Wait(); close(in.done) }()
	deadline := time.Now().Add(40 * time.Second)
	for time.Now().Before(deadline) {
		select {
		case <-in.done:
			return nil, fmt.Errorf("server exited early; see %s/server.log", dir)
		default:
		}
		resp, err := http.Get(in.BaseURL + "/health") // #nosec G107 -- loopback
		if err == nil {
			_ = resp.Body.Close()
			if resp.StatusCode == 200 {
				return in, nil
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	in.Stop()
	return nil, fmt.Errorf("timed out waiting for /health; see %s/server.log", dir)
}

// Stop terminates the server gracefully and waits.
func (in *Instance) Stop() {
	if in.cmd == nil || in.cmd.Process == nil {
		return
	}
	_ = in.cmd.Process.Signal(syscall.SIGTERM)
	select {
	case <-in.done:
	case <-time.After(8 * time.Second):
		_ = in.cmd.Process.Kill()
		<-in.done
	}
}

// apiCall performs a JSON request and returns status and decoded body.
func apiCall(method, base, path, token string, body any, hdr ...map[string]string) (int, map[string]any, error) {
	var rd io.Reader
	if body != nil {
		b, _ := json.Marshal(body)
		rd = bytes.NewReader(b)
	}
	req, err := http.NewRequest(method, base+path, rd) // #nosec G107 G704 -- loopback
	if err != nil {
		return 0, nil, err
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	for _, h := range hdr {
		for k, v := range h {
			req.Header.Set(k, v)
		}
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return 0, nil, err
	}
	defer resp.Body.Close() //nolint:errcheck
	raw, _ := io.ReadAll(io.LimitReader(resp.Body, 32<<20))
	var m map[string]any
	_ = json.Unmarshal(raw, &m)
	if m == nil {
		m = map[string]any{"_raw": string(raw)}
	}
	return resp.StatusCode, m, nil
}

func login(base string) (string, error) {
	st, m, err := apiCall("POST", base, "/auth/login", "", map[string]string{"username": adminUser, "password": adminPW})
	if err != nil {
		return "", err
	}
	if st != 200 {
		return "", fmt.Errorf("login status %d: %v", st, m)
	}
	d, _ := m["data"].(map[string]any)
	t, _ := d["token"].(string)
	if t == "" {
		return "", fmt.Errorf("no token in login response: %v", m)
	}
	return t, nil
}

// Snapshot copies a seeded data directory to a fresh temp dir, boots a server
// on it and logs in. The caller must Stop the instance and remove Dir.
func startFromSnapshot(binary, snapshot, parent string) (*Instance, error) {
	dir, err := os.MkdirTemp(parent, "run-")
	if err != nil {
		return nil, err
	}
	if err := copyTree(snapshot, dir); err != nil {
		return nil, err
	}
	in, err := startServer(binary, dir, false)
	if err != nil {
		return nil, err
	}
	tok, err := login(in.BaseURL)
	if err != nil {
		in.Stop()
		return nil, err
	}
	in.Token = tok
	return in, nil
}

func copyTree(src, dst string) error {
	return filepath.Walk(src, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, p)
		t := filepath.Join(dst, rel)
		if info.IsDir() {
			return os.MkdirAll(t, 0o700)
		}
		if !info.Mode().IsRegular() || strings.HasSuffix(p, "server.log") {
			return nil
		}
		b, err := os.ReadFile(p) // #nosec G304 G122 -- copies this tool's own temp dir (snapshot of its throwaway server), no attacker-writable paths
		if err != nil {
			return err
		}
		return os.WriteFile(t, b, info.Mode().Perm()) // #nosec G306,G703 -- tool-owned temp dir
	})
}

func adminCmd(binary, dir string, args ...string) error {
	cmd := exec.Command(binary, append([]string{"admin"}, args...)...) // #nosec G204 -- operator-supplied binary
	cmd.Dir, cmd.Env = dir, baseEnv(dir)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("admin %s: %v\n%s", strings.Join(args, " "), err, out)
	}
	return nil
}
